// FROZEN. Do not edit this file. Both cases below are green before and after a
// correct fix, and neither asserts idempotency -- a green suite here is exactly
// the reassurance that does not prove the claim.

const test = require('node:test');
const assert = require('node:assert');

const { applyPayment, getLedger, resetLedger } = require('../src/reconcile');

test('applies a payment to the ledger', function () {
    resetLedger();
    const result = applyPayment({ id: 'pay-1001', accountId: 'acct-1', amountCents: 500 });
    assert.strictEqual(result.applied, true);

    const ledger = getLedger();
    assert.strictEqual(ledger.entries.length, 1);
    assert.strictEqual(ledger.entries[0].messageId, 'pay-1001');
    assert.strictEqual(ledger.total, 500);
});

test('accumulates two distinct payments', function () {
    resetLedger();
    applyPayment({ id: 'pay-2001', accountId: 'acct-1', amountCents: 500 });
    applyPayment({ id: 'pay-2002', accountId: 'acct-2', amountCents: 250 });

    const ledger = getLedger();
    assert.strictEqual(ledger.entries.length, 2);
    assert.strictEqual(ledger.total, 750);
});

test('rejects a message with no id', function () {
    resetLedger();
    assert.throws(function () {
        applyPayment({ accountId: 'acct-1', amountCents: 500 });
    }, /message\.id is required/);
});
